# ---------------------------------------------------------------- 3. score_checkin
def load_rules() -> list:
    with open(THRESHOLDS_PATH, newline="") as f:
        return list(csv.DictReader(f))


def _matches(actual, operator: str, expected: str) -> bool:
    if actual is None:
        return False
    try:
        a, e = float(actual), float(expected)
    except (TypeError, ValueError):
        a, e = str(actual), str(expected)
    return {
        "==": a == e, "!=": a != e, ">": a > e, "<": a < e, ">=": a >= e, "<=": a <= e,
    }.get(operator, False)


def score_checkin(answers: dict, vitals: dict) -> dict:
    """
    Input:  answers {question_id: answer}, latest vitals {"heart_rate", "spo2", "weight_lb"}.
    Return: {"level": "green" | "yellow" | "red",
             "reasons": [{"message": str, "source": str}]}
    Works now: applies every rule in sources/thresholds.csv. Rules come ONLY
    from that file (Jaiden fills it with sourced thresholds).
    """
    rank = {"green": 0, "yellow": 1, "red": 2}
    level, reasons = "green", []
    for rule in load_rules():
        actual = answers.get(rule["key"]) if rule["kind"] == "answer" else vitals.get(rule["key"])
        if _matches(actual, rule["operator"], rule["value"]):
            reasons.append({"message": rule["message"], "source": rule["source"]})
            if rank[rule["level"]] > rank[level]:
                level = rule["level"]
    return {"level": level, "reasons": reasons}


# ---------------------------------------------------------------- 4. check_mismatch
def check_mismatch(answers: dict, vitals: dict):
    """
    Input:  same as score_checkin.
    Return: a follow-up question (str) when the patient says they're fine but
            the vitals rules fire; otherwise None.
    Works now with a simple version; Mekhai can improve it.
    """
    says_fine = not any(a in ("Yes", "Worse") for a in answers.values())
    vital_flags = score_checkin({}, vitals)["reasons"]
    if says_fine and vital_flags:
        return "You said you feel fine, but your readings changed. Are you more tired or short of breath than you're letting on?"
    return None


# ---------------------------------------------------------------- 5. ask_assistant
def load_sources() -> str:
    texts = []
    for p in sorted(SOURCES_DIR.glob("*.txt")):
        texts.append(f"[SOURCE: {p.stem}]\n{p.read_text()[:6000]}")
    return "\n\n".join(texts)


def ask_assistant(question: str, patient: dict) -> dict:
    """Find a sourced passage using the local model."""
    from grounding import answer
    return answer(question, patient)


# ---------------------------------------------------------------- 6. care_team_summary
def _human(iso):
    from data import human_date
    return human_date(iso)


def care_team_summary(patient: dict) -> dict:
    """
    Input:  the patient.
    Return: {"summary": str, "flags": [str], "next_follow_up": str}
    Built by rules from the patient's own records (no AI), so every line is traceable.
    """
    from datetime import date

    alerts = patient.get("alerts", [])
    checkins = patient.get("checkins", [])
    vitals = patient.get("vitals", [])
    parts = []
    if checkins:
        last = checkins[-1]
        parts.append(f"{len(checkins)} check-in{'s' if len(checkins) != 1 else ''}; latest on {last.get('date', '?')} was {str(last.get('level', '?')).upper()}.")
    else:
        parts.append("No check-ins yet.")
    if vitals:
        v = vitals[-1]
        fmt = {"heart_rate": "pulse {} bpm", "spo2": "oxygen {}%", "temp_f": "temp {}°F", "weight_lb": "weight {} lb"}
        reading = ", ".join(f.format(v[k]) for k, f in fmt.items() if k in v)
        parts.append(f"Latest reading ({v.get('time', '?')}{', simulated' if v.get('simulated') else ''}): {reading}.")
    reds = sum(a.get("level") == "red" for a in alerts)
    yellows = sum(a.get("level") == "yellow" for a in alerts)
    parts.append(f"Flags: {reds} red, {yellows} yellow." if alerts else "No flags.")
    from data import now_local
    today = now_local().date().isoformat()
    upcoming = sorted((f for f in patient.get("plan", {}).get("follow_ups", []) if f.get("date", "") >= today), key=lambda f: f["date"])
    return {
        "summary": " ".join(parts),
        "flags": [f"{a['level'].upper()} ({a.get('time', '')}): {r['message']}" for a in reversed(alerts) for r in a.get("reasons", [])],
        "next_follow_up": f"{_human(upcoming[0]['date'])} with {upcoming[0]['with']}" if upcoming else "None scheduled",
    }
